11	import { defaultReason } from "@/lib/outfits/predict-occasion";
12	import { searchCities, type City } from "@/lib/weather/geocode";
13	import { getCurrentPosition, permissionState, GeoError } from "@/lib/weather/geolocate";
14	import type { LocationSource } from "@/lib/weather/location";
15	import type { GenerateResult, Look, UiOccasion, WeatherPayload } from "@/lib/generator/types";
