96	  // The fix is parked in a ref until both gates are known, so geolocation still
97	  // starts immediately rather than waiting on the first generate to return.
98	  const userChoseRef = useRef(false);
99	  const pendingGeoRef = useRef<Chosen | null>(null);
100	  const geoAllowedRef = useRef<boolean | null>(null); // null = stored origin unknown yet
101	
102	  const applyPendingGeo = useCallback(() => {
103	    if (userChoseRef.current) return; // gate 1
104	    if (geoAllowedRef.current !== true) return; // gate 2
105	    const fix = pendingGeoRef.current;
106	    if (!fix) return;
107	    pendingGeoRef.current = null;
108	    setCity(fix);
109	  }, []);
110	
111	  useEffect(() => {
112	    let cancelled = false;
113	    permissionState().then((state) => {
114	      if (cancelled) return;
115	      if (state === "unsupported") {
116	        setGeoSupported(false);
117	        return;
118	      }
