238	    setStatus("loading");
239	    generate({ occasion, formality, lean, city: city ?? undefined }).then((res) => {
240	      if (cancelled) return;
241	      applyResult(res);
242	    });
243	    return () => {
244	      cancelled = true;
245	    };
246	  }, [seeded, occasion, formality, lean, city, nonce, applyResult]);
247	
248	  /**
249	   * The only path that spends an AI call on a day already answered.
250	   *
251	   * Deliberately a direct call rather than an effect dependency: a flag routed
252	   * through the effect can still be in flight when the user switches occasion,
253	   * and would then regenerate that occasion too.
