271	      occasion={occasion}
272	      cities={cities}
273	      refineOpen={refineOpen}
274	      missing={missing}
275	      limitMessage={limitMessage}
276	      locating={locating}
277	      geoError={geoError}
278	      reason={reason}
279	      onOccasion={(o) => {
280	        setOccasion(o);
281	        setReason(defaultReason(o));
282	        // A new occasion is a new set of looks — drop the remembered index.
283	        desiredLookRef.current = null;
284	        writeParams({ occasion: o, look: null });
285	        // A tap that departs from the prediction is the flywheel signal for the
286	        // future learner. Fire-and-forget — it must never disturb the looks.
287	        if (o !== predictedRef.current) {
288	          logOccasionOverride({ predicted: predictedRef.current, chosen: o }).catch(() => {});
289	        }
290	      }}
291	      onOpenRefine={() => setRefineOpen(true)}
292	      onCloseRefine={() => setRefineOpen(false)}
293	      onRefineApply={({ formality: f, lean: c }) => {
294	        setFormality(f);
295	        setLean(c);
296	        setRefineOpen(false);
297	      }}
298	      onCityChange={(c) => {
299	        userChoseRef.current = true;
300	        pendingGeoRef.current = null;
301	        setCity({ lat: c.lat, lon: c.lon, label: c.name, source: "city" });
302	      }}
303	      onCitySearch={(q) => {
304	        if (q.trim().length < 2) return;
305	        searchCities(q).then(setCities);
306	      }}
307	      onUseMyLocation={geoSupported ? useMyLocation : undefined}
308	      onSelectLook={(i) => {
309	        desiredLookRef.current = i || null;
310	        setSelectedLook(i);
311	        writeParams({ look: i === 0 ? null : String(i) });
312	      }}
313	      onRetry={() => setNonce((n) => n + 1)}
314	      onRegenerate={regenerate}
315	    />
316	  );
317	}
